use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let input = input.as_array().unwrap();
    let cents = input[0].as_u64().unwrap();
    let n = input[1].as_u64().unwrap();
    let mut result = Value::new_array();
    let mut count = 0;
    for _ in 0..n {
        let mut share = Value::new_array();
        for _ in 0..n {
            let num = Value::new_i64(count);
            share.push(num);
            count += 1;
        }
        result.push(share);
    }
    result
}
